/* Build flags for every vendored curl TU (vcurl_*.c). First-party; a refresh
 * leaves it alone.
 *
 * vytoc has no per-package -D (#link is the only directive), so the flags a
 * curl build normally gets on its command line are defined here instead, and
 * every wrapper includes this file before the upstream source:
 *
 *   BUILDING_LIBCURL   compile the library, not a client of it
 *   CURL_STATICLIB     no __declspec(dllimport) on the API; net_shim.c and
 *                      http_shim.c define it too, so both sides agree
 *   HAVE_CONFIG_H      take curl_config.h (generated by refresh-curl.sh from a
 *                      real configure; curl's own config-win32.h is MSVC-only)
 *
 * MBEDTLS_USER_CONFIG_FILE has to match vyto_mbedtls_build.h exactly: curl's
 * vtls/mbedtls.c reads mbedTLS's headers, and a TU that saw a different
 * configuration than the library was compiled with would disagree about
 * struct layouts. */
#ifndef VYTO_CURL_BUILD_H
#define VYTO_CURL_BUILD_H
#define BUILDING_LIBCURL 1
#define CURL_STATICLIB 1
#define HAVE_CONFIG_H 1
#define MBEDTLS_USER_CONFIG_FILE "vyto_mbedtls_user.h"
#endif
